/* Preserve the existing SQLite task oracle and negative probes; add statistical interpretation. */
const evalMetrics=infraReadableHTML(
 '<div class="mechanism-core" id="evaluation-metric-contract">'+knowledgeSubhead('评估先分两道题：系统做对没有，评分器判对没有')+
 para('任务评估有三种单位：任务是一个目标，试次是从指定初始状态运行一次，尝试是试次内的一次模型或工具调用。同一任务重跑三次就有三个试次；每个试次可能有多次工具尝试。任务身份、试次身份和尝试身份分开记录，不能把三次工具成功当成三个任务成功。',
 '第一道题检验系统：合法任务应该完成，越权任务应该拒绝。第二道题检验评分器：真实合格产物该接收，不合格产物该拦截。两道题都有正负例，但标签含义不同；不能把评分器准确率当成Agent任务成功率。独立环境oracle是按契约读取实际状态的判定程序，也需要用故意构造的错误产物检验。')+
 table(['评分器的判定','真实合格产物','真实不合格产物'],[
 ['接收','真阳性TP：正确接收','假阳性FP：错放行'],
 ['拒绝','假阴性FN：错拒绝','真阴性TN：正确拦截']])+
 para('设人工/确定性规则确认6份合格、6份不合格，评分器接收其中5份合格和2份不合格。则TP=5、FP=2、FN=1、TN=4；准确率(5+4)/12=75%，接收结果中真正合格的精确率5/7≈71.43%，合格产物召回率5/6≈83.33%。高后果发布更关注错放行类别，不能因总体75%便忽略两份错误产物。',
 '系统任务也会类别不平衡。另设5个可完成、20个应拒绝任务，全部拒绝就能拿20/25=80%的总体符合预期率，但合法任务完成召回为0。两类召回分别0%与100%，宏平均为50%；宏平均让每类等权，任务加权总体让每题等权，回答的是不同问题。没有接收任何结果时精确率分母为0，应标未定义，不能写成100%。安全错误还应单列门禁，不能只靠加权平均兑换。')+'</div>');

const evalIntervals=infraReadableHTML(
 knowledgeSubhead('5题全对不等于普遍可靠：同时写计数、区间与样本来源')+
 para('观察到5/5与100/100都等于100%，但样本提供的信息量不同。用Wilson比例区间、双侧95%与z≈1.959964，5/5区间约[56.55%,100%]，100/100约[96.30%,100%]。它提醒我们：少量题全对仍不足以给未见任务很强的保证。区间不能弥补抽样偏差，专挑容易题得到一万个全对，也没有证明难题可用。')+
 knowledgeFormula('Wilson区间 · n>0，p̂=k/n','中心 = (p̂ + z²/(2n)) / (1 + z²/n)；半宽 = z√[p̂(1−p̂)/n + z²/(4n²)] / (1 + z²/n)','上下界为中心±半宽。这里只用于独立、同一成功机制的二项观察示例；n=0拒绝计算。')+
 figure('v25-wilson-counts','Matplotlib按实际统计程序结果绘制。示例是合成计数；比例区间不把任务选择、相关性和评分错误自动纳入。')+
 para('频率学的95%指这套构造方法在条件成立时的重复抽样覆盖表现，不是“本次真实成功概率有95%落在区间内”。同一模板改名字得到100题、同一故障连续重试100次，都可能有强相关；不能机械把它们当100个独立证据。真实评估应按任务来源、类别和重复试次保留层次，必要时按任务或来源成组重抽样，并说明方法。',
 '还要分清描述固定题集和推断未来任务。一个固定回归集本次通过18/25，是这25题的准确描述；若把它当未来成功率估计，需要解释题集怎样代表部署分布、样本是否独立，以及工具和评分器有没有变化。超时和崩溃从受理集合进入分母，未成熟试次单列；不能只对有漂亮产物的部分计算区间。')+
 knowledgeCheck('把同一个成功样本复制100份，能直接得到更可靠的100/100区间吗？','不能。复制没有带来100份独立信息。应按独立任务来源计算有效证据，并保留重复试次结构；区间公式里的n不是可以随意复制出来的数量。'));

const evalPaired=infraReadableHTML(
 knowledgeSubhead('版本比较要保留同题配对，不只看两个百分比')+
 para('固定同25题、相同初始状态、预算和评分器。教学CSV给出：A通过18题，B通过20题，看起来从72%到80%，增加8个百分点（相对增加约11.11%，两者不要混称）。但同题结果如何变化，只有成对记录才能看见。这里两者都通过16题，仅A通过2题，仅B通过4题，两者都失败3题。真正方向不同的只有6题。')+
 figure('v25-paired-outcomes','25条固定合成配对标签。成对检验看仅A与仅B两格；该图不是实际模型基准。')+
 para('若零假设下两个方向等可能，且各题对独立，6个变化中落向B的次数可按二项分布Binomial(6,0.5)考察。本例双侧精确p=2×P(X≤2)=2×(1+6+15)/64=0.6875。p考察的是零假设下出现同样或更极端偏向的结果有多常见，不是“B更好的概率”。这份小样本不足以据此宣布B有普遍优势；p大也不证明两版本等价。证明等价需要事先定义可接受差异与相应设计，不能把“没发现差异”改写成“没有差异”。',
 '两份边际Wilson区间是否重叠，不能替代上述成对检验。若每题有多次试次，先固定每题如何聚合、预算怎样一致，再采用尊重任务层次的方法；不能拆散相关试次虚增样本数。比较多个版本或大量切片时，先指定主要指标与门槛，保留探索性结果，避免从许多波动里挑一个好看的宣布胜出。',
 '评分器也要版本化。换了判分规则，应对同一批已保存产物重新评分，区分行为变化和尺子变化；换了环境快照、检索索引或权限，也应分开记录。开发集负责调试，留出集只按约定节奏验收，持续看着同一批留出题修改提示会让它逐渐变成开发集。泄露或不再代表部署的数据应有更新策略。'));

const evalStatsPractice=infraReadableHTML(
 knowledgeSubhead('统计实战：用固定标签核对分母、区间和配对')+cmeLab('evaluation_statistics.py')+
 '<details class="full-code"><summary>展开完整paired-example.csv：25题固定配对标签</summary>'+code('paired-example.csv','CSV',configMemoryEvaluationFiles['paired-example.csv'])+'</details>'+
 para('原SQLite实战验证执行与评分边界，这个程序验证统计解释，两者各有自己的证据。先手算四格16/2/4/3，再核对18/25、20/25与精确p。若把“仅B通过”从4改为8，同时增加4道新题，则题数变29、A仍18、B变24；不能只改一个百分比而仍沿用25的分母或原p值。')+
 knowledgeCheck('总体提高8个百分点，某关键越权切片退化，能发布吗？','不能只凭总体决定。事先定义不可接受的安全错误、关键类别门槛、预算与统计条件；保留失败轨迹和实际效果。总体改善不能抵消已经发生的禁止行为。'));

{
 const a=articles.find(a=>a.id==='agent-evaluation'),old=a.sections.slice();
 a.sections=[old[0],old[1],old[2],['指标与评分器：类别、错放行和分母',evalMetrics],['样本与区间：全对、独立性和抽样来源',evalIntervals],old[3],old[4],old[5],['版本比较：同题配对、预算和评分尺子',evalPaired],old[6],old[7],['统计实战与变化题：完整标签和独立计算',evalStatsPractice]];
 a.refs=nitRefs([...a.refs,'v25Wilson','v25McNemar']);a.minutes=65;a.updated='2026.11.05';
 a.objectives=['定义任务、试次、尝试和可检验的任务完成条件','验证评分器并解释类别、计数、区间和同题差异','运行环境oracle与统计夹具，区分执行证据和真实模型能力'];
}
{
 const d=infraDomain('agent'),p=d.points.find(p=>p.id==='ag-evaluation');
 p.body=evalMetrics+p.body+evalIntervals+evalPaired;
 d.refs=nitRefs([...d.refs,'v25Wilson','v25McNemar']);
}
const evaluationCasesBeforeCME=infraFieldCases.agent;
infraFieldCases.agent=()=>'<h3>评估统计：执行结果和统计可信度分开核对</h3>'+cmeLab('evaluation_statistics.py',false)+linkTo('agent-evaluation','阅读任务oracle、评分器校准和同题比较')+evaluationCasesBeforeCME();
